P={{CLAUDE}}/../packs; [ -d "$P/usage" ] && [ -d "$P/repo-orkeon-workshop" ] || { printf 'ok (skipped: no packs folder beside the harness - a deployed workshop)'; exit 0; }; python3 -c 'import os, re, sys
P = sys.argv[1]
bad = []
def front(path):
    m = re.match(r"---\n(.*?)\n---\n(.*)\Z", open(path, encoding="utf-8").read(), re.S)
    return (m.group(1), m.group(2)) if m else ("", "")
f, body = front(os.path.join(P, "usage/claude/skills/token-usage/SKILL.md"))
desc = re.search(r'"'"'^description: "([^"\n]+)"$'"'"', f, re.M)
if not re.search(r"^name: token-usage$", f, re.M): bad.append("token-usage:name")
if not desc or len(desc.group(1)) > 240: bad.append("token-usage:description")
if re.search(r"^disable-model-invocation:", f, re.M): bad.append("token-usage:not-model-invocable")
if len(body.splitlines()) > 60: bad.append("token-usage:body>60")
for s in ("ws-check", "ws-migrate", "ws-image", "ws-docs"):
    f, body = front(os.path.join(P, "repo-orkeon-workshop/claude/skills", s, "SKILL.md"))
    if not re.search(r"^name: %s$" % s, f, re.M): bad.append(s + ":name")
    if not re.search(r'"'"'^description: "[^"\n]+"$'"'"', f, re.M): bad.append(s + ":description")
    if not re.search(r"^disable-model-invocation: true$", f, re.M): bad.append(s + ":model-invocable")
    if len(body.splitlines()) > 60: bad.append(s + ":body>60")
summary = "token-usage %d chars, model-invocable; ws-* 4 user-invoked" % len(desc.group(1)) if desc else ""

if bad:
    sys.stdout.write("FAIL " + " ".join(bad))
    sys.exit(1)
sys.stdout.write("ok (" + summary + ")")
' "$P"
